"""matplotlib.figure — Figure class for the plotly backend.

Mirrors upstream's `matplotlib.figure.Figure` surface so OO-style
matplotlib code works:

    from matplotlib.figure import Figure
    fig = Figure()
    ax = fig.add_subplot(111)
    ax.plot([1, 2, 3], [4, 5, 6])
    fig.suptitle("hi")
    fig.savefig("out.png")

Every method either delegates to `matplotlib.pyplot` (when there's a
direct equivalent) or maps to a Plotly layout / trace operation.
"""

import sys as _sys

from matplotlib.artist import Artist


def _plt():
    """Late-bound pyplot import — pyplot already imports axes which
    imports this module, so we can't import pyplot at module load."""
    from matplotlib import pyplot as _p
    return _p


# Shared no-op fallback for unknown Figure methods.
_figure_warned = set()

def _figure_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    if name not in _figure_warned:
        _figure_warned.add(name)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] figure.Figure.{name}() not implemented — "
                f"returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class Figure(Artist):
    """Plotly-backed Figure. Single-figure model — there's at most one
    live plotly figure at a time, owned by the pyplot module. This
    class is a thin facade over `_plt().gcf()`."""

    __getattr__ = _figure_getattr_fallback

    def __init__(self, figsize=None, dpi=None, facecolor=None,
                 edgecolor=None, linewidth=0.0, frameon=None,
                 subplotpars=None, tight_layout=None,
                 constrained_layout=None, layout=None, **kwargs):
        super().__init__()
        self._figsize = figsize or (8, 6)
        self._dpi = dpi or 100
        self._facecolor = facecolor
        self._edgecolor = edgecolor
        self._linewidth = linewidth
        self._tight_layout = tight_layout
        self._constrained_layout = constrained_layout
        self._layout_engine = layout
        # Cache of Axes keyed by their subplot spec so repeated calls
        # to add_subplot / gca with the same args return the same axes.
        self._axes_cache = {}
        self._artists = []
        self._suptitle_text = ''
        self._supxlabel_text = ''
        self._supylabel_text = ''
        # Pre-seed the pyplot figure so `_plt().gcf()` returns it.
        try:
            _plt()._ensure_fig()
        except Exception:
            pass

    # ─── Figure-level operations ───────────────────────────────

    def _make_axes(self, key, *, nrows=1, ncols=1, row=1, col=1, **kwargs):
        """Build or retrieve a cached Axes for ``key``. Honours nrows/
        ncols/row/col so multi-panel layouts get distinct Axes."""
        if key in self._axes_cache:
            return self._axes_cache[key]
        from matplotlib.pyplot import _Axes, _SafeFigure, _ensure_fig
        ax = _Axes(_SafeFigure(_ensure_fig()), row=row, col=col,
                    nrows=nrows, ncols=ncols)
        self._axes_cache[key] = ax
        return ax

    def add_subplot(self, *args, **kwargs):
        """Return the Axes for the given subplot spec. Repeated calls
        with the same spec return the same Axes instance."""
        # Parse upstream's flexible spec.
        if not args:
            nrows, ncols, idx = 1, 1, 1
        elif len(args) == 1 and isinstance(args[0], int):
            # 3-digit shorthand: 111, 224, …
            s = args[0]
            nrows, ncols, idx = s // 100, (s // 10) % 10, s % 10
        elif len(args) == 3:
            nrows, ncols, idx = args
        else:
            nrows, ncols, idx = 1, 1, 1
        # 1-based index → row, col
        row = (idx - 1) // ncols + 1
        col = (idx - 1) % ncols + 1
        return self._make_axes(('subplot', nrows, ncols, idx),
                                nrows=nrows, ncols=ncols, row=row, col=col,
                                **kwargs)

    def add_axes(self, rect, projection=None, **kwargs):
        return self._make_axes(('axes', tuple(rect) if hasattr(rect, '__iter__')
                                  else rect), **kwargs)

    def add_gridspec(self, nrows, ncols, **kwargs):
        from matplotlib.gridspec import GridSpec
        return GridSpec(nrows, ncols, **kwargs)

    def subplots(self, nrows=1, ncols=1, **kwargs):
        return _plt().subplots(nrows=nrows, ncols=ncols, **kwargs)

    def subplot_mosaic(self, mosaic, **kwargs):
        return _plt().subplot_mosaic(mosaic, **kwargs)

    def subplots_adjust(self, **kwargs):
        _plt().subplots_adjust(**kwargs)

    def tight_layout(self, **kwargs):
        _plt().tight_layout(**kwargs)

    def savefig(self, fname, **kwargs):
        return _plt().savefig(fname, **kwargs)

    def show(self, *args, **kwargs):
        return _plt().show(*args, **kwargs)

    def clf(self, keep_observers=False):
        _plt().clf()
        self._axes_cache.clear()
        self._artists.clear()

    def clear(self, keep_observers=False):
        self.clf(keep_observers)

    def gca(self, **kwargs):
        # Default current-axes: 111 if nothing has been added.
        if self._axes_cache:
            # Return the most recently created axes.
            return next(reversed(self._axes_cache.values()))
        return self.add_subplot(111)

    def get_axes(self):
        return list(self._axes_cache.values())

    @property
    def axes(self):
        return self.get_axes()

    @axes.setter
    def axes(self, value):
        # Artist.__init__ sets self.axes = None; ignore — the property
        # already derives the list from the figure's children.
        pass

    def delaxes(self, ax):
        for key, val in list(self._axes_cache.items()):
            if val is ax:
                del self._axes_cache[key]
                return

    # ─── Titles / text overlays ────────────────────────────────

    def suptitle(self, t, **kwargs):
        self._suptitle_text = str(t) if t is not None else ''
        _plt().suptitle(t, **kwargs)

    def supxlabel(self, t, **kwargs):
        self._supxlabel_text = str(t) if t is not None else ''
        _plt().xlabel(t, **kwargs)

    def supylabel(self, t, **kwargs):
        self._supylabel_text = str(t) if t is not None else ''
        _plt().ylabel(t, **kwargs)

    def text(self, x, y, s, **kwargs):
        _plt().figtext(x, y, s, **kwargs)

    def legend(self, *args, **kwargs):
        return _plt().legend(*args, **kwargs)

    def colorbar(self, mappable=None, ax=None, **kwargs):
        return _plt().colorbar(mappable, ax=ax, **kwargs)

    # ─── Size / DPI / colour ───────────────────────────────────

    def set_size_inches(self, w, h=None, forward=True):
        if h is None and hasattr(w, '__len__'): w, h = w
        self._figsize = (float(w), float(h))
        try:
            fig = _plt().gcf()
            fig.update_layout(width=int(w * self._dpi),
                              height=int(h * self._dpi))
        except Exception: pass

    def get_size_inches(self): return self._figsize
    def set_figheight(self, h, forward=True): self.set_size_inches(self._figsize[0], h)
    def set_figwidth(self, w, forward=True):  self.set_size_inches(w, self._figsize[1])
    def get_figheight(self): return self._figsize[1]
    def get_figwidth(self):  return self._figsize[0]
    def set_dpi(self, dpi):  self._dpi = float(dpi)
    def get_dpi(self):       return self._dpi

    def set_facecolor(self, color):
        self._facecolor = color
        try:
            from matplotlib.pyplot import _color_to_str
            _plt().gcf().update_layout(paper_bgcolor=_color_to_str(color))
        except Exception: pass

    def get_facecolor(self): return self._facecolor
    def set_edgecolor(self, color): self._edgecolor = color
    def get_edgecolor(self): return self._edgecolor
    def set_frameon(self, b): pass
    def get_frameon(self): return True

    # ─── Layout engines (no-op) ────────────────────────────────

    def set_constrained_layout(self, b): self._constrained_layout = bool(b)
    def get_constrained_layout(self): return bool(self._constrained_layout)
    def set_tight_layout(self, b):    self._tight_layout = bool(b)
    def get_tight_layout(self): return bool(self._tight_layout)
    def set_layout_engine(self, layout=None, **kwargs):
        self._layout_engine = layout
    def get_layout_engine(self): return self._layout_engine
    def execute_constrained_layout(self, renderer=None): pass

    # ─── Misc ──────────────────────────────────────────────────

    def get_children(self):
        """Return all artists currently registered on the figure —
        cached axes plus any free-form artists added via add_artist."""
        return list(self._axes_cache.values()) + list(self._artists)

    def findobj(self, match=None, include_self=True):
        """Walk the figure's child tree, returning artists matching
        ``match`` (a class or predicate). Mirrors Artist.findobj."""
        results = [self] if include_self else []
        for child in self.get_children():
            # Recurse into children that themselves expose findobj.
            try:
                results.extend(child.findobj(match=match, include_self=True))
            except Exception:
                results.append(child)
        if match is None:
            return results
        if isinstance(match, type):
            return [r for r in results if isinstance(r, match)]
        return [r for r in results if callable(match) and match(r)]

    def draw(self, renderer=None): pass
    def canvas_draw(self): pass
    def autofmt_xdate(self, *args, **kwargs): pass
    def align_labels(self, axs=None): pass
    def align_xlabels(self, axs=None): pass
    def align_ylabels(self, axs=None): pass
    def number(self): return 1
    def set_canvas(self, canvas): pass
    def stale(self): return False


class SubFigure(Figure):
    """Sub-figure facade — same surface as Figure in this shim."""
    def __init__(self, parent, subplotspec=None, **kwargs):
        super().__init__(**kwargs)
        self._parent = parent


class FigureBase(Figure):
    """Compatibility alias — upstream's FigureBase is the shared
    superclass of Figure and SubFigure."""
    pass


# Re-export for any code that does `from matplotlib.figure import figaspect`.
def figaspect(arg):
    """Compute a figure size with the right aspect for the given arg.
    `arg` can be a scalar (height/width ratio) or a 2-D array."""
    try:
        import numpy as np
        a = np.asarray(arg)
        if a.ndim == 2:
            ratio = a.shape[0] / max(1, a.shape[1])
        else:
            ratio = float(arg)
    except Exception:
        ratio = float(arg)
    w = 8.0
    return (w, w * ratio)


# ─── Added: missing methods on Figure / SubFigure / FigureBase ──────


def _attach_figure_methods(cls):
    """Glue the rest of upstream's Figure API surface onto :class:`Figure`.
    Mostly state getters/setters and bbox helpers; the plotly backend
    handles the actual rendering so these are bookkeeping shims."""

    # FigureBase methods ──────────────────────────────────────────

    def add_artist(self, artist, clip=False):
        """Add a freeform artist to the figure. Records it on the
        figure's own children list."""
        if not hasattr(self, '_artists'):
            self._artists = []
        self._artists.append(artist)
        return artist

    def add_subfigure(self, subplotspec=None, **kwargs):
        """Create a :class:`SubFigure` nested inside this one."""
        return SubFigure(self, subplotspec=subplotspec, **kwargs)

    def subfigures(self, nrows=1, ncols=1, **kwargs):
        """Create a grid of subfigures. Returns a 2-D array of
        :class:`SubFigure` instances (or a single one when both
        dimensions are 1)."""
        if nrows == 1 and ncols == 1:
            return SubFigure(self)
        return [[SubFigure(self) for _ in range(ncols)] for _ in range(nrows)]

    def align_titles(self, axs=None):
        """Align axes titles across a row. No-op in the plotly backend."""
        pass

    def get_suptitle(self):
        return getattr(self, '_suptitle_text', '')

    def get_supxlabel(self):
        return getattr(self, '_supxlabel_text', '')

    def get_supylabel(self):
        return getattr(self, '_supylabel_text', '')

    def get_tightbbox(self, renderer=None, *, bbox_extra_artists=None):
        return None

    def get_default_bbox_extra_artists(self):
        return []

    def get_linewidth(self):
        return self._linewidth

    def set_linewidth(self, lw):
        self._linewidth = float(lw)

    @property
    def frameon(self):
        return self.get_frameon()

    @frameon.setter
    def frameon(self, b):
        self.set_frameon(b)

    def sca(self, ax):
        """Set the current axes for this figure. The shim threads the
        choice through pyplot."""
        try: _plt().sca(ax)
        except Exception: pass
        return ax

    # Figure methods ──────────────────────────────────────────────

    def add_axobserver(self, func):
        """Register a callback to be invoked when the figure's axes
        change (added / removed). The shim stores the callbacks but
        never fires them — the static figure model has no axes events."""
        if not hasattr(self, '_axobservers'):
            self._axobservers = []
        self._axobservers.append(func)

    @property
    def dpi(self):
        return self._dpi

    @dpi.setter
    def dpi(self, v):
        self._dpi = float(v)

    def draw_artist(self, artist):
        """Draw a single artist on this figure. No-op for the plotly
        backend — the trace pipeline handles the actual drawing."""
        pass

    def draw_without_rendering(self):
        """Walk the figure's draw tree without actually rasterising.
        Used by layout solvers to discover artist sizes. No-op in the
        plotly backend."""
        pass

    def figimage(self, X, xo=0, yo=0, alpha=None, norm=None, cmap=None,
                 vmin=None, vmax=None, origin=None, resize=False, **kwargs):
        """Place an image directly on the figure (not in any axes)."""
        from matplotlib.image import FigureImage
        im = FigureImage(self, cmap=cmap, norm=norm, offsetx=xo, offsety=yo,
                         origin=origin)
        im.set_data(X)
        return im

    def get_constrained_layout_pads(self, *, w_pad=False, h_pad=False,
                                     wspace=False, hspace=False):
        """Return the constrained-layout padding values. Without a real
        solver we return the canonical defaults."""
        return (0.04167, 0.04167, 0.02, 0.02)

    def set_constrained_layout_pads(self, *, w_pad=None, h_pad=None,
                                     wspace=None, hspace=None):
        """Set the constrained-layout padding values. Cached for return
        from :meth:`get_constrained_layout_pads`."""
        if not hasattr(self, '_cl_pads'):
            self._cl_pads = {}
        for k, v in dict(w_pad=w_pad, h_pad=h_pad, wspace=wspace,
                          hspace=hspace).items():
            if v is not None:
                self._cl_pads[k] = v

    def ginput(self, n=1, timeout=30, show_clicks=True, mouse_add=1,
                mouse_pop=3, mouse_stop=2):
        """Block until the user clicks ``n`` points (or ``timeout``
        elapses). The plotly backend doesn't run a blocking event loop,
        so we return an empty list."""
        return []

    def waitforbuttonpress(self, timeout=-1):
        """Block until a key/mouse event. Returns None on timeout.
        No-op in the plotly backend."""
        return None

    # Attach everything to cls.
    _l = locals()
    for n in ('add_artist', 'add_subfigure', 'subfigures', 'align_titles',
              'get_suptitle', 'get_supxlabel', 'get_supylabel',
              'get_tightbbox', 'get_default_bbox_extra_artists',
              'get_linewidth', 'set_linewidth', 'sca',
              'add_axobserver', 'draw_artist', 'draw_without_rendering',
              'figimage', 'get_constrained_layout_pads',
              'set_constrained_layout_pads', 'ginput', 'waitforbuttonpress'):
        if n in _l:
            setattr(cls, n, _l[n])
    cls.frameon = _l['frameon']
    cls.dpi = _l['dpi']


_attach_figure_methods(Figure)
# SubFigure also exposes `canvas` — proxy to the parent.
SubFigure.canvas = property(lambda self: getattr(self._parent, 'canvas', None))


# Figure.figure property — returns self for upstream compatibility.
Figure.figure = property(lambda self: self)
